-- Authenticated production check with existing managers. All data is rolled back.
begin;
do $$declare a1 uuid;a2 uuid;r uuid;s uuid;i uuid;p uuid;q uuid;v jsonb;t text:='TEST-DIRECTIONS-'||gen_random_uuid()::text;d date:=(now() at time zone 'Africa/Cairo')::date;blocked boolean:=false;begin
select a.user_id into a1 from public.admins a where a.role='super_admin' and a.active and a.user_id is not null and not exists(select 1 from clinic_finance.shifts sh where sh.cashier_id=a.id and sh.status<>'reviewed') order by a.id limit 1;
select user_id into a2 from public.admins where role='super_admin' and active and user_id<>a1 order by id limit 1;if a1 is null or a2 is null then raise exception 'Two existing managers required';end if;
perform set_config('request.jwt.claim.sub',a1::text,true);execute 'set local role authenticated';r:=public.clinic_finance_save_register(null,t,1000,'receive');s:=public.clinic_finance_open_shift(r,gen_random_uuid());i:=public.clinic_finance_invoice(t,t,'خدمة اختبار تراجع',500,gen_random_uuid());
perform public.clinic_finance_collect(i,s,'cash',100,t||'-CASH',gen_random_uuid());p:=public.clinic_finance_collect(i,s,'instapay',200,t||'-INSTA',gen_random_uuid());perform public.clinic_finance_collect(i,s,'pos',50,t||'-VISA',gen_random_uuid());
begin perform public.clinic_finance_request(jsonb_build_object('kind','expense','shift_id',s,'amount',10,'reason','صرف مخالف','evidence',t||'-DENY'),gen_random_uuid());exception when others then if sqlerrm like '%للاستلام فقط%' then blocked:=true;else raise;end if;end;if not blocked then raise exception 'Receive-only payout accepted';end if;
q:=public.clinic_finance_request(jsonb_build_object('kind','general_expense','category','electricity','method','instapay','amount',30,'reason','فاتورة كهرباء اختبار','evidence',t||'-ELEC'),gen_random_uuid());perform set_config('request.jwt.claim.sub',a2::text,true);perform public.clinic_finance_review_request(q,true,'فحص واعتماد فاتورة اختبار');v:=public.clinic_finance_snapshot(d,d);if not exists(select 1 from jsonb_array_elements(v->'disbursements')x where x->>'id'=q::text and x->>'category'='electricity' and x->'details'->>'method'='instapay') then raise exception 'Unified review metadata missing';end if;
perform set_config('request.jwt.claim.sub',a1::text,true);q:=public.clinic_finance_request(jsonb_build_object('kind','refund','payment_id',p,'amount',50,'reason','رد تحويل اختبار','evidence',t||'-REF'),gen_random_uuid());perform set_config('request.jwt.claim.sub',a2::text,true);perform public.clinic_finance_review_request(q,true,'رد بنفس قناة السداد');
perform set_config('request.jwt.claim.sub',a1::text,true);perform public.clinic_finance_close_shift(s,jsonb_build_object('100',1),'جرد فعلي اختبار');perform set_config('request.jwt.claim.sub',a2::text,true);perform public.clinic_finance_review_shift(s,'مطابقة الجرد');
perform set_config('request.jwt.claim.sub',a1::text,true);perform public.clinic_finance_save_register(r,t,1000,'pay');s:=public.clinic_finance_open_shift(r,gen_random_uuid());blocked:=false;begin perform public.clinic_finance_collect(i,s,'pos',10,t||'-DENY-POS',gen_random_uuid());exception when others then if sqlerrm like '%للصرف فقط%' then blocked:=true;else raise;end if;end;if not blocked then raise exception 'Pay-only collection accepted';end if;
q:=public.clinic_finance_request(jsonb_build_object('kind','general_expense','category','water','method','cash','shift_id',s,'amount',20,'reason','فاتورة مياه اختبار','evidence',t||'-WATER'),gen_random_uuid());perform set_config('request.jwt.claim.sub',a2::text,true);perform public.clinic_finance_review_request(q,true,'اعتماد مياه اختبار');execute 'reset role';
if (select sum(l.debit-l.credit) from clinic_finance.lines l join clinic_finance.entries e on e.id=l.entry_id where e.shift_id=s and l.account='1111')<>-20 then raise exception 'Wrong payout';end if;
if exists(select 1 from clinic_finance.entries e join clinic_finance.lines l on l.entry_id=e.id where e.source_id in (p,q) group by e.id having sum(l.debit-l.credit)<>0) then raise exception 'Unbalanced journal';end if;
end $$;
rollback;
select jsonb_build_object('test','register directions and InstaPay rollback passed','remaining_test_registers',(select count(*) from clinic_finance.registers where name like 'TEST-DIRECTIONS-%'),'remaining_test_invoices',(select count(*) from clinic_finance.invoices where reference like 'TEST-DIRECTIONS-%'),'anonymous_save_blocked',not has_function_privilege('anon','public.clinic_finance_save_register(uuid,text,numeric,text)','execute'));
